def uleb(T, i):
    val = 0; shift = 0; n = 0
    while True:
        b = T[i+n]
        val += (b & 0x7f) << shift
        shift += 7
        n += 1
        if b < 128:
            break
    return val, n

# Bits: all ones except VFPOnlySP(32), HasV8Ops(43), MClass(16)
BITS = ~( (1<<32) | (1<<43) | (1<<16) )
MASK64 = (1<<64)-1
BITS &= MASK64

ARM_ModeThumb = 1<<44
ARM_HasV6Ops = 1<<40
ARM_HasV8Ops = 1<<43
ARM_FeatureCRC = 1<<5
ARM_HasV5TEOps = 1<<37
ARM_HasV4TOps = 1<<36
ARM_HasV5TOps = 1<<38
ARM_FeatureTrustZone = 1<<22
ARM_HasV6T2Ops = 1<<41
ARM_HasV7Ops = 1<<39
ARM_FeatureMP = 1<<17
ARM_FeatureDB = 1<<8
ARM_FeatureHWDivARM = 1<<13
ARM_FeatureNaClTrap = 1<<20
ARM_FeatureNEON = 1<<18
ARM_FeatureCrypto = 1<<24
ARM_FeatureFP16 = 1<<26
ARM_FeatureVFP4 = 1<<28
ARM_FeatureThumb2 = 1<<27
ARM_HasV6MOps = 1<<42
ARM_FeatureMClass = 1<<16
ARM_FeatureT2XtPk = 1<<9
ARM_FeatureDSPThumb2 = 1<<29
ARM_FeatureVFP2 = 1<<25
ARM_FeatureVFP3 = 1<<30
ARM_FeatureVFPOnlySP = 1<<32
ARM_FeatureFPARMv8 = 1<<11
ARM_FeatureHWDiv = 1<<14
ARM_HasV5TEOps = 1<<37

def predicate(idx):
    B = BITS
    if idx == 0: return not (B & ARM_ModeThumb)
    if idx == 1: return (not (B & ARM_ModeThumb)) and (B & ARM_HasV6Ops)
    if idx == 2: return (not (B & ARM_ModeThumb)) and (B & ARM_HasV8Ops) and (B & ARM_FeatureCRC)
    if idx == 3: return (not (B & ARM_ModeThumb)) and (B & ARM_HasV5TEOps)
    if idx == 4: return not (B & ARM_HasV8Ops)
    if idx == 5: return (not (B & ARM_ModeThumb)) and (B & ARM_HasV8Ops)
    if idx == 6: return (not (B & ARM_ModeThumb)) and (B & ARM_HasV4TOps)
    if idx == 7: return (not (B & ARM_ModeThumb)) and (B & ARM_HasV5TOps)
    if idx == 8: return (not (B & ARM_ModeThumb)) and (B & ARM_FeatureTrustZone)
    if idx == 9: return (not (B & ARM_ModeThumb)) and (B & ARM_HasV6T2Ops)
    if idx == 10: return (not (B & ARM_ModeThumb)) and (B & ARM_HasV7Ops)
    if idx == 11: return (not (B & ARM_ModeThumb)) and (B & ARM_HasV7Ops) and (B & ARM_FeatureMP)
    if idx == 12: return (not (B & ARM_ModeThumb)) and (B & ARM_FeatureDB)
    if idx == 13: return (not (B & ARM_ModeThumb)) and (B & ARM_FeatureHWDivARM)
    if idx == 14: return (not (B & ARM_ModeThumb)) and (B & ARM_FeatureNaClTrap)
    if idx == 15: return (B & ARM_FeatureNEON)
    if idx == 16: return (B & ARM_HasV8Ops) and (B & ARM_FeatureCrypto)
    if idx == 17: return (B & ARM_FeatureNEON) and (B & ARM_FeatureFP16)
    if idx == 18: return (B & ARM_FeatureNEON) and (B & ARM_FeatureVFP4)
    if idx == 19: return (B & ARM_ModeThumb)
    if idx == 20: return (B & ARM_ModeThumb) and (B & ARM_HasV5TOps)
    if idx == 21: return (B & ARM_ModeThumb) and (B & ARM_HasV6Ops)
    if idx == 22: return (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2)
    if idx == 23: return not (B & ARM_FeatureMClass)
    if idx == 24: return (B & ARM_ModeThumb) and (B & ARM_HasV8Ops)
    if idx == 25: return (B & ARM_ModeThumb) and (B & ARM_HasV6MOps)
    if idx == 26: return (B & ARM_ModeThumb) and (B & ARM_HasV5TOps) and not (B & ARM_FeatureMClass)
    if idx == 27: return (B & ARM_FeatureT2XtPk) and (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2)
    if idx == 28: return (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2) and not (B & ARM_HasV8Ops)
    if idx == 29: return (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2) and (B & ARM_FeatureDSPThumb2)
    if idx == 30: return (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2) and (B & ARM_HasV7Ops)
    if idx == 31: return (B & ARM_ModeThumb) and (B & ARM_FeatureDB)
    if idx == 32: return (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2) and not (B & ARM_FeatureMClass)
    if idx == 33: return (B & ARM_ModeThumb) and (B & ARM_FeatureMClass)
    if idx == 34: return (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2) and (B & ARM_HasV8Ops)
    if idx == 35: return (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2) and (B & ARM_FeatureTrustZone)
    if idx == 36: return (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2) and (B & ARM_HasV7Ops) and (B & ARM_FeatureMP)
    if idx == 37: return (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2) and (B & ARM_FeatureT2XtPk)
    if idx == 38: return (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2) and (B & ARM_HasV8Ops) and (B & ARM_FeatureCRC)
    if idx == 39: return (B & ARM_FeatureHWDiv) and (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2)
    if idx == 40: return (not (B & ARM_HasV8Ops)) and (B & ARM_ModeThumb) and (B & ARM_FeatureThumb2)
    if idx == 41: return (B & ARM_FeatureVFP2)
    if idx == 42: return (B & ARM_FeatureVFP2) and not (B & ARM_FeatureVFPOnlySP)
    if idx == 43: return (B & ARM_FeatureVFP4)
    if idx == 44: return (B & ARM_FeatureVFP4) and not (B & ARM_FeatureVFPOnlySP)
    if idx == 45: return (B & ARM_FeatureVFP3)
    if idx == 46: return (B & ARM_FeatureFPARMv8)
    if idx == 47: return (B & ARM_FeatureVFP3) and not (B & ARM_FeatureVFPOnlySP)
    if idx == 48: return (B & ARM_FeatureFPARMv8) and not (B & ARM_FeatureVFPOnlySP)
    if idx == 49: return (B & ARM_HasV8Ops) and (B & ARM_FeatureNEON)
    raise Exception("unknown predicate idx %d" % idx)

def field(insn, start, ln):
    mask = ((1 << ln) - 1) << start
    return (insn & mask) >> start

def simulate(T, insn):
    """returns (opc, didx) or None; mirrors decodeInstruction"""
    ptr = 0
    cur = 0
    n = len(T)
    while True:
        if ptr >= n:
            return None
        op = T[ptr]
        if op == 1:
            start, ln = T[ptr+1], T[ptr+2]
            ptr += 3
            cur = field(insn, start, ln)
        elif op == 2:
            val, l = uleb(T, ptr+1)
            ptr2 = ptr + 1 + l
            skip = T[ptr2] | (T[ptr2+1] << 8)
            nxt = ptr2 + 2
            if val != cur:
                ptr = nxt + skip
            else:
                ptr = nxt
        elif op == 3:
            start, ln = T[ptr+1], T[ptr+2]
            fv = field(insn, start, ln)
            val, l = uleb(T, ptr+3)
            ptr2 = ptr + 3 + l
            skip = T[ptr2] | (T[ptr2+1] << 8)
            nxt = ptr2 + 2
            if val != fv:
                ptr = nxt + skip
            else:
                ptr = nxt
        elif op == 4:
            pidx, l = uleb(T, ptr+1)
            ptr2 = ptr + 1 + l
            skip = T[ptr2] | (T[ptr2+1] << 8)
            nxt = ptr2 + 2
            if not predicate(pidx):
                ptr = nxt + skip
            else:
                ptr = nxt
        elif op == 5:
            opc, l1 = uleb(T, ptr+1)
            didx, l2 = uleb(T, ptr+1+l1)
            return (opc, didx)
        elif op == 6:
            # SoftFail - just continue
            pmask, l1 = uleb(T, ptr+1)
            nmask, l2 = uleb(T, ptr+1+l1)
            ptr = ptr + 1 + l1 + l2
        elif op == 7:
            return None
        else:
            return None

